def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    n = len(x)
    level = statistics.median(x[-min(12, n):])
    if n < 36:
        return [float(level)] * horizon
    start = max(24, n - min(100, n // 2))
    base_errors = [abs(x[t] - statistics.median(x[max(0, t - 12):t])) for t in range(start, n)]
    base = statistics.median(base_errors) if base_errors else 0.0
    best_p = None
    best = float('inf')
    upper = min(180, n // 2)
    for p in range(12, upper + 1):
        lo = max(start, p)
        errors = [abs(x[t] - x[t - p]) for t in range(lo, n)]
        if len(errors) >= 12:
            score = statistics.median(errors) + 0.25 * statistics.mean(errors)
            if score < best:
                best = score
                best_p = p
    if best_p is None or (base > 0.0 and best >= 0.92 * base):
        return [float(level)] * horizon
    p = best_p
    cycle = x[-p:]
    if len(x) >= 2 * p:
        previous = x[-2 * p:-p]
        shift = statistics.median(cycle[i] - previous[i] for i in range(p))
        step_scale = statistics.median(abs(cycle[i] - cycle[i - 1]) for i in range(1, p))
        if step_scale > 0.0 and abs(shift) <= 3.0 * step_scale:
            shift *= 0.15
        else:
            shift = 0.0
    else:
        shift = 0.0
    return [float(cycle[k % p] + shift * (1.0 - math.exp(-(k + 1) / float(p)))) for k in range(horizon)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    n = len(x)
    fallback = statistics.median(x[-min(12, n):])
    if n < 70:
        return [float(fallback)] * horizon
    w = min(30, max(18, n // 8))
    target = x[-w:]
    target_center = statistics.median(target)
    target_shape = [v - target_center for v in target]
    candidates = []
    max_start = n - w - 8
    for s in range(0, max_start + 1):
        if s + w > n - w:
            continue
        window = x[s:s + w]
        center = statistics.median(window)
        distance = statistics.median(abs((window[i] - center) - target_shape[i]) for i in range(w))
        candidates.append((distance, s, center))
    if not candidates:
        return [float(fallback)] * horizon
    candidates.sort(key=lambda q: q[0])
    distances = [q[0] for q in candidates]
    typical = statistics.median(distances)
    chosen = [q for q in candidates[:5] if typical == 0.0 or q[0] <= 0.85 * typical]
    if not chosen:
        return [float(fallback)] * horizon
    recent_scale = statistics.median(abs(x[i] - x[i - 1]) for i in range(max(1, n - 30), n))
    out = []
    for k in range(horizon):
        values = []
        for distance, s, center in chosen:
            j = s + w + k
            if j < n:
                values.append(x[j] + target_center - center)
        if values:
            spread = max(values) - min(values)
            if recent_scale > 0.0 and spread > 2.0 * recent_scale:
                y = statistics.median(values)
                y = 0.65 * y + 0.35 * fallback
            else:
                y = statistics.median(values)
        elif out:
            y = out[-1]
        else:
            y = fallback
        out.append(float(y))
    return out

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    n = len(x)
    if n < 30:
        level = statistics.median(x[-min(10, n):])
        return [float(level)] * horizon
    validation_start = max(20, n - min(90, n // 2))
    periods = list(range(12, min(180, n // 2) + 1))
    period_scores = []
    for p in periods:
        errors = [abs(x[t] - x[t - p]) for t in range(max(validation_start, p), n)]
        if len(errors) >= 10:
            period_scores.append((statistics.mean(errors), p))
    best_period = min(period_scores)[1] if period_scores else None
    errors = {'level': [], 'trend': [], 'periodic': []}
    for t in range(validation_start, n):
        past = x[:t]
        level = statistics.median(past[-min(12, len(past)):])
        errors['level'].append(abs(x[t] - level))
        if len(past) >= 8:
            half = 4
            slope = (statistics.median(past[-half:]) - statistics.median(past[-2 * half:-half])) / half
            slope = max(-0.01, min(0.01, slope))
        else:
            slope = 0.0
        errors['trend'].append(abs(x[t] - (level + slope * math.exp(-1.0 / 12.0))))
        if best_period is not None and t >= best_period:
            errors['periodic'].append(abs(x[t] - x[t - best_period]))
    scores = {}
    for name, vals in errors.items():
        if vals:
            scores[name] = statistics.mean(vals)
    base_score = scores.get('level', 0.0)
    usable = {k: v for k, v in scores.items() if v >= 0.0 and (base_score == 0.0 or v <= 0.95 * base_score)}
    if not usable:
        usable = {'level': max(base_score, 1e-12)}
    weights = {k: 1.0 / max(v, 1e-12) for k, v in usable.items()}
    total_weight = sum(weights.values())
    level_now = statistics.median(x[-12:])
    slope_now = (statistics.median(x[-4:]) - statistics.median(x[-8:-4])) / 4.0
    slope_now = max(-0.01, min(0.01, slope_now))
    cycle = x[-best_period:] if best_period is not None else []
    out = []
    for k in range(horizon):
        predictions = {'level': level_now, 'trend': level_now + slope_now * 12.0 * (1.0 - math.exp(-(k + 1) / 12.0))}
        if cycle:
            predictions['periodic'] = cycle[k % best_period]
        y = sum(weights[name] * predictions[name] for name in weights if name in predictions)
        z = sum(weights[name] for name in weights if name in predictions)
        out.append(float(y / z if z else level_now))
    return out
